CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TYPE user_role AS ENUM ('CLIENT','FREELANCER','ADMIN');
CREATE TYPE service_status AS ENUM ('DRAFT','PUBLISHED','PAUSED','REMOVED');
CREATE TYPE booking_status AS ENUM ('PENDING_PAYMENT','PAID','ACCEPTED','IN_PROGRESS','COMPLETED','REJECTED','CANCELLED');
CREATE TYPE payment_status AS ENUM ('PENDING','SUCCEEDED','FAILED','REFUNDED');
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(120) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password_hash TEXT NOT NULL, role user_role NOT NULL DEFAULT 'CLIENT', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE freelancer_profiles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE, title VARCHAR(160) NOT NULL, bio TEXT NOT NULL, skills TEXT[] NOT NULL DEFAULT '{}', category VARCHAR(80) NOT NULL, location VARCHAR(120) NOT NULL, latitude NUMERIC, longitude NUMERIC, profile_image TEXT, experience SMALLINT NOT NULL DEFAULT 0, rating NUMERIC(2,1) NOT NULL DEFAULT 0, completed_orders INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE services (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), freelancer_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, title VARCHAR(180) NOT NULL, description TEXT NOT NULL, category VARCHAR(80) NOT NULL, price NUMERIC(10,2) NOT NULL CHECK (price >= 0), currency CHAR(3) NOT NULL DEFAULT 'USD', delivery_days SMALLINT NOT NULL CHECK (delivery_days > 0), skills TEXT[] NOT NULL DEFAULT '{}', image_url TEXT, status service_status NOT NULL DEFAULT 'DRAFT', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE bookings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), client_id UUID NOT NULL REFERENCES users(id), freelancer_id UUID NOT NULL REFERENCES users(id), service_id UUID NOT NULL REFERENCES services(id), requirements TEXT NOT NULL, notes TEXT, deadline DATE, price NUMERIC(10,2) NOT NULL CHECK (price >= 0), currency CHAR(3) NOT NULL DEFAULT 'USD', status booking_status NOT NULL DEFAULT 'PENDING_PAYMENT', payment_status payment_status NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ);
CREATE TABLE booking_status_history (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, previous_status booking_status, new_status booking_status NOT NULL, changed_by UUID NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID UNIQUE NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, provider VARCHAR(40) NOT NULL, provider_payment_id VARCHAR(180), amount NUMERIC(10,2) NOT NULL, currency CHAR(3) NOT NULL, status payment_status NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE reviews (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID UNIQUE NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, client_id UUID NOT NULL REFERENCES users(id), freelancer_id UUID NOT NULL REFERENCES users(id), rating SMALLINT NOT NULL CHECK (rating BETWEEN 1 AND 5), comment TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX services_category_status_idx ON services(category,status); CREATE INDEX bookings_client_idx ON bookings(client_id); CREATE INDEX bookings_freelancer_idx ON bookings(freelancer_id);
